import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Rollout and manual acceptance","description":"","frontmatter":{},"headers":[],"relativePath":"feature/credit-unification/rollout.md","filePath":"feature/credit-unification/rollout.md"}'),o={name:"feature/credit-unification/rollout.md"};function r(s,e,d,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="rollout-and-manual-acceptance" tabindex="-1">Rollout and manual acceptance <a class="header-anchor" href="#rollout-and-manual-acceptance" aria-label="Permalink to &quot;Rollout and manual acceptance&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>All new generation fees use DA-974. Caption generate/refine/adapt share CAPTION_VARIANTS. No token/GPU metering, Payment provisioning, content-writing, editor prompt, publish or mock Studio screen changes.</p><h3 id="database-delta" tabindex="-1">Database delta <a class="header-anchor" href="#database-delta" aria-label="Permalink to &quot;Database delta&quot;">​</a></h3><p>Apply <code>docs/database/migrations/2026-10-21-unified-ai-credit.sql</code> after existing Caption/Video tables and compact Credit accounting/execution migrations. Fresh databases use <code>docs/database/init-postgres-v2.sql</code> only.</p><table tabindex="0"><thead><tr><th>Table</th><th>Change</th></tr></thead><tbody><tr><td>ai_video_jobs</td><td>Nullable reservation_id FK, unique non-null reservation index, CHECK excluding simultaneous usage_id + reservation_id</td></tr><tr><td>ai_caption_generations</td><td>credits INT → BIGINT; existing values/history preserved</td></tr><tr><td>DA-974 grant/reservation/allocation/price tables</td><td>No new columns/tables; new requests use existing accounting/execution metadata</td></tr><tr><td>Legacy ledgers/limits/usages</td><td>Retained, not imported/deleted; legacy refund tail only</td></tr></tbody></table><p>The Agency seeder no longer invents random legacy usage or Owner caps. It does not grant money; explicit authorized DEV_SEED remains the dev-funding entry point. Existing seeded legacy rows remain untouched.</p><h2 id="before-deployment" tabindex="-1">Before deployment <a class="header-anchor" href="#before-deployment" aria-label="Permalink to &quot;Before deployment&quot;">​</a></h2><ol><li>Inspect open legacy jobs, current grants/prices and schema on the intended database. Freeze relevant Business/workers before DDL and do not run an old billing build afterward.</li><li>Apply the new SQL with <code>psql -X -v ON_ERROR_STOP=1 -f &lt;migration-path&gt;</code>. It is transactional with bounded lock/statement timeouts. Do not edit old teammates&#39; migrations or replay all migration files recursively.</li><li>Deploy matching Business and Web together. Workspace POST <code>/captions</code>, <code>/captions/refine</code>, <code>/captions/adapt</code>, <code>/videos</code> now require <code>Idempotency-Key</code>. Web service helper supplies it; external callers need updating. API URLs/bodies/result fields remain; credit amounts are long, Video adds creditsHeld (creditsUsed=0 while held). Existing generic AI routes keep their request-hash convention and Workspace header.</li><li>Admin configures missing operation prices. Do not insert guessed prices or treat missing pricing as free. Agency needs a real grant or explicitly authorized test grant and a cycle anchor. Owner has no personal ceiling, not unlimited funds.</li></ol><h2 id="manual-test" tabindex="-1">Manual test <a class="header-anchor" href="#manual-test" aria-label="Permalink to &quot;Manual test&quot;">​</a></h2><p>Use an Agency with test funds and a Workspace where the actor is Owner/Manager/Creator. Test configured prices with the existing editor adapters; standalone mock Studio pages are not newly connected.</p><ul><li>Caption first generation: one charge, one history row, remaining decreases by the configured price. Retry the same key/body: same generationId, no second provider call/charge. Change payload/action with that key: 409.</li><li>Refine and Adapt: both use CAPTION_VARIANTS, one request fee even when multiple platforms return. Choice/trend-fit/status/styles/history reads remain free.</li><li>Video: PENDING holds, not charges; COMPLETED with video_url charges once; explicit FAILED releases once. Timeout/unknown does not refund. Close browser and allow workers to finish; history/status should converge. Another member must not read the original user&#39;s Video job.</li><li>Member ceiling 0/missing price/insufficient Agency funds: reject before dispatch. Owner bypasses only personal ceiling. Price changes affect new requests, not active reservations.</li><li>Workspace Credit and Agency reporting agree on available/used/held. Dashboard shows explicit subscription period and a nonzero error state when setup is missing. Legacy seeded usage must not appear in current totals.</li></ul><h2 id="local-read-only-preflight-2026-10-21" tabindex="-1">Local read-only preflight (2026-10-21) <a class="header-anchor" href="#local-read-only-preflight-2026-10-21" aria-label="Permalink to &quot;Local read-only preflight (2026-10-21)&quot;">​</a></h2><p><code>brandhub-postgres/brandhub</code>: legacy open Video jobs=0; latest enabled Content price=3/revision2, Ambassador=10/revision1; the other five operations have no configured price. The new reservation_id column is absent: new migration has NOT been applied to this application database. No local/demo/shared DB or Atlas mutation was performed during implementation.</p><h2 id="remaining-live-acceptance" tabindex="-1">Remaining live acceptance <a class="header-anchor" href="#remaining-live-acceptance" aria-label="Permalink to &quot;Remaining live acceptance&quot;">​</a></h2><p>Real JWT/Gateway/provider calls and a complete paid AI run remain for deployment testing. Browser checks used fixtures; backend checks used a dedicated PostgreSQL container and fake AI. Restart the matching Business build after migration; SQL alone does not prove HTTP/provider readiness. Unknown-outcome manual reconciliation UI and actual Payment/Subscription integration remain outside this change.</p><h2 id="local-apply-receipt-—-2026-10-21" tabindex="-1">Local APPLY receipt — 2026-10-21 <a class="header-anchor" href="#local-apply-receipt-—-2026-10-21" aria-label="Permalink to &quot;Local APPLY receipt — 2026-10-21&quot;">​</a></h2><p>After explicit user request and confirmation that Business/workers were stopped, rechecked: no listener on 8081, zero other sessions on <code>brandhub-postgres/brandhub.public</code>, zero open Video jobs. Applied only <code>2026-10-21-unified-ai-credit.sql</code> with ON_ERROR_STOP; transaction COMMIT succeeded. Earlier Credit schema effects were already present and were not replayed. This supersedes the preflight&#39;s pending-APPLY state above for this local database only.</p><p>Postcheck PASS: Caption credits is bigint; Video reservation_id is nullable uuid; FK/CHECK validated; unique partial reservation index valid. Application schema readiness query returns true. Pre/post counts unchanged: Caption/Video/reservation/allocation/legacy usage=0 each, grants=1. DEV_SEED amount=100, used=0, held=0 unchanged. No init, seed, cleanup, guessed prices, Atlas changes or service restart. Start the matching Business build before live acceptance; missing Admin operation prices still need configuration.</p>',19)])])}const g=a(o,[["render",r]]);export{h as __pageData,g as default};
